def get_plant_signes(plant: str) -> dict:
    plant = str(plant).strip()
    if plant not in PLANT_CONFIGS:
        raise ValueError(f"Plant '{plant}' non configuré. Plants disponibles : {', '.join(sorted(PLANT_CONFIGS))}")
    return PLANT_CONFIGS[plant]["signes"].copy()
